package com.gomgomapps.math.core;
import java.util.*;
/** Read the actually displayed division operands in slash, bracket or fraction notation. */
public final class DivisionNotations {
 private DivisionNotations(){}
 public static final String ID="divisionNotations",PROMPT="나눗셈에 나타난 두 수와 정확한 값을 쓰세요.";
 public static final Catalog.Skill SKILL=new Catalog.Skill(ID,"나눗셈의 세 가지 표기",6,1,1,"","divisionNotations",1000000,"divide","나누기 기호, 긴 나눗셈 기호, 분수 표기를 같은 나눗셈으로 읽는다.");
 public record Givens(int dividend,int divisor,int notation){}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){int first=limits.givenMinimum(0),last=limits.givenMaximum(1000000),low=limits.contextDivisorMinimum(),high=limits.contextDivisorMaximum();if(first<0||first>last||last>1000000||low<1||low>high||high>99)throw new IllegalArgumentException("Division notation curriculum");int width=high-low+1;return IndexedQuestionSupply.choose((last-first+1)*width*3,i->make(first+i/(width*3),low+i/3%width,i%3),random,limits,recent);}
 public static Question make(int a,int b,int notation){if(a<0||a>1000000||b<1||b>99||notation<0||notation>2)throw new IllegalArgumentException("Division notation bounds");Question q=new Question(ID,PROMPT,"",""+a,""+b,Rational.of(a,b).toString());q.diagram=new StudyDiagram("divisionNotation",new double[]{a,b,notation});q.labels=new String[]{"나누어지는 수","나누는 수","정확한 값"};q.answerFormat="fraction";q.decimal=true;q.stepSupport=false;attach(q);return q;}
 public static Givens read(Question q){return q==null||!ID.equals(q.skillId)||!PROMPT.equals(q.prompt)?null:readDiagram(q.diagram);}
 public static Givens readDiagram(StudyDiagram diagram){if(diagram==null||!diagram.type.equals("divisionNotation")||diagram.values.length!=3)return null;double[] v=diagram.values;if(Arrays.stream(v).anyMatch(n->!Double.isFinite(n)||n!=(int)n)||v[0]<0||v[0]>1000000||v[1]<1||v[1]>99||v[2]<0||v[2]>2)return null;return new Givens((int)v[0],(int)v[1],(int)v[2]);}
 public static void attach(Question q){Givens g=read(q);if(g==null)return;StudyGuide guide=new StudyGuide().transfer(false);guide.teachingVersion="division-notations-v1";String[] dividend={"÷ 앞의 수를 쓰세요.","긴 나눗셈 기호 안의 수를 쓰세요.","분수 선 위의 수를 쓰세요."},divisor={"÷ 뒤의 수를 쓰세요.","긴 나눗셈 기호 왼쪽의 수를 쓰세요.","분수 선 아래의 수를 쓰세요."};guide.step(dividend[g.notation],"나누어지는 수 = ","",""+g.dividend);guide.step(divisor[g.notation],"나누는 수 = ","",""+g.divisor);guide.step("정수 몫을 쓰세요.","정수 몫 = ","",""+(g.dividend/g.divisor));guide.step("나머지를 쓰세요.","나머지 = ","",""+(g.dividend%g.divisor));guide.step("정수 몫에 나머지를 나눈 값을 더하세요.","정수 몫 + 나머지 ÷ 나누는 수 = ","",Rational.of(g.dividend,g.divisor).toString());q.studyGuide=guide;}
 public static Checker.Result check(Question q,List<String> answers){Givens g=read(q);if(g==null||answers==null||answers.size()!=3)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");for(int i=0;i<3;i++){String raw=answers.get(i);if(raw==null||raw.isBlank()||raw.length()>120)return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"답 입력 필요");raw=Expression.normalize(raw.trim());if(!(i<2?raw.matches("0|[1-9][0-9]{0,6}"):raw.matches("[0-9]{1,12}(?:[.][0-9]{1,12})?(?:/[0-9]{1,12})?")))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수 입력 필요");try{Rational expected=i==0?Rational.of(g.dividend):i==1?Rational.of(g.divisor):Rational.of(g.dividend,g.divisor);if(!Expression.number(raw).equals(expected))return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 답 확인");}catch(RuntimeException invalid){return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수 입력 필요");}}return new Checker.Result(Checker.Status.CORRECT,-1,"정답");}
}
